@layer components {
  :where([data-control-family="switch"][data-slot="root"]) {
    --switch-background: oklch(from var(--foreground) l c h / 0.14);
    --switch-hover-background: oklch(from var(--foreground) l c h / 0.2);
    --switch-checked-background: var(--primary);
    --switch-checked-hover-background: oklch(from var(--primary) l c h / 0.9);
    --switch-thumb-radius: 9999px;
    --switch-thumb-background: var(--background);
    border-radius: 9999px;
    background: var(--switch-background);
    outline: none;
    transition: background-color var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="switch"][data-slot="root"]:hover) {
    background: var(--switch-hover-background);
  }

  :where([data-control-family="switch"][data-slot="root"]:active) {
    background: oklch(from var(--foreground) l c h / 0.25);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked]) {
    background: var(--switch-checked-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked]:hover) {
    background: var(--switch-checked-hover-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked]:active) {
    background: oklch(from var(--primary) l c h / 0.8);
  }

  :where([data-control-family="switch"][data-slot="root"]:focus-visible) {
    box-shadow: 0 0 0 2px oklch(from var(--foreground) l c h / 0.3);
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled]) {
    opacity: 0.5;
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled]:hover) {
    background: var(--switch-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled][data-checked]:hover) {
    background: var(--switch-checked-background);
  }

  :where([data-control-family="switch"][data-slot="thumb"]) {
    border-radius: var(--switch-thumb-radius);
    background: var(--switch-thumb-background);
    box-shadow: var(--shadow-sm);
    transition-property: translate, width;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled] [data-slot="thumb"]) {
    opacity: 0.8;
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"]) {
    color: oklch(from var(--foreground) l c h / 0.7);
    transition-property: color, opacity;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-slot="thumb-icon"]:not([data-switch-icon="unchecked"])) {
    color: var(--primary-text);
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"][data-switch-icon="unchecked"]) {
    color: oklch(from var(--foreground) l c h / 0.6);
    opacity: 1;
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-switch-icon="unchecked"]) {
    opacity: 0;
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"][data-switch-icon="checked"]) {
    color: var(--primary-text);
    opacity: 0;
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-switch-icon="checked"]) {
    opacity: 1;
  }

  :where([data-control-family="switch"][data-slot="root"]) {
    border-radius: calc(infinity * 1px);
    --_switch-root-outline: none;
    outline-style: var(--_switch-root-outline);
  }

  :where([data-control-family="switch"][data-slot="thumb"][data-checked]) {
    --_switch-thumb-translate: calc(var(--spacing) * 4) 0;
    translate: var(--_switch-thumb-translate);
  }

  :where([data-control-family="switch"][data-slot="thumb"]:is(:where(.group\/switch):active *)[data-checked]) {
    --_switch-thumb-translate: calc(var(--spacing) * 3) 0;
    translate: var(--_switch-thumb-translate);
  }
}

@property --switch-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --switch-hover-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --switch-checked-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --switch-checked-hover-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --switch-thumb-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --switch-thumb-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";
import type { ReactNode } from "react";
import type { SwitchProps } from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

// Own anatomy, not restyled Button way Toggle is.
// thumb stretches on press and its checked offset shrinks by same amount, so it stays flush right while widening.
export function Switch({
  className,
  checked,
  defaultChecked,
  onCheckedChange,
  disabled,
  readOnly,
  required,
  name,
  value,
  id,
  icon,
  checkedIcon,
  uncheckedIcon,
  ...props
}: SwitchProps) {
  const hasStateIcons = checkedIcon !== undefined || uncheckedIcon !== undefined;
  const hasIcon = icon !== undefined || hasStateIcons;
  const singleIcon = hasStateIcons ? undefined : icon;
  const onIcon = checkedIcon ?? icon;
  const offIcon = uncheckedIcon ?? icon;
  return (
    <SwitchPrimitive.Root
      data-control-ui="switch"
      data-control-family="switch"
      data-slot="root"
      checked={checked}
      defaultChecked={defaultChecked}
      onCheckedChange={onCheckedChange}
      disabled={disabled}
      readOnly={readOnly}
      required={required}
      name={name}
      value={value}
      id={id}
      nativeButton
      render={<button type="button" />}
      className={cn(
        "group/switch relative inline-flex h-5 w-9 shrink-0 cursor-pointer items-center p-0.5",
        "data-[disabled]:cursor-not-allowed",
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-control-ui="switch"
        data-control-family="switch"
        data-slot="thumb"
        className={cn("pointer-events-none relative block size-4", "group-active/switch:w-5")}
      >
        {hasIcon ? <SwitchThumbIcon icon={singleIcon} checkedIcon={onIcon} uncheckedIcon={offIcon} /> : null}
      </SwitchPrimitive.Thumb>
    </SwitchPrimitive.Root>
  );
}

// decorative — Switch's own role and label carry meaning
function SwitchThumbIcon({ icon, checkedIcon, uncheckedIcon }: { icon?: ReactNode; checkedIcon?: ReactNode; uncheckedIcon?: ReactNode }) {
  const base = "absolute inset-0 flex items-center justify-center [&_svg]:size-2.5 [&_svg]:stroke-[2.5]";

  if (icon !== undefined) {
    return (
      <span aria-hidden data-control-ui="switch" data-control-family="switch" data-slot="thumb-icon" className={base}>
        {icon}
      </span>
    );
  }

  return (
    <>
      {uncheckedIcon !== undefined ? (
        <span
          aria-hidden
          data-control-ui="switch"
          data-control-family="switch"
          data-slot="thumb-icon"
          data-switch-icon="unchecked"
          className={base}
        >
          {uncheckedIcon}
        </span>
      ) : null}
      {checkedIcon !== undefined ? (
        <span
          aria-hidden
          data-control-ui="switch"
          data-control-family="switch"
          data-slot="thumb-icon"
          data-switch-icon="checked"
          className={base}
        >
          {checkedIcon}
        </span>
      ) : null}
    </>
  );
}
